#!/usr/bin/env bash
set -euo pipefail

# Applies a configuration SQL file generated by tools/export-config-sql.php.
# Usage: bash deploy/linux/apply-config.sh /tmp/kqcenter-config-YYYYMMDD-HHMMSS.sql

SQL_PATH="${1:?Usage: apply-config.sh <kqcenter-config.sql>}"
BACKUP_PATH="${KQCENTER_BACKUP_PATH:-/var/backups/k-qcenter}"
STAMP="$(date -u +%Y%m%d-%H%M%S)"

test -f "$SQL_PATH"
head -n 1 "$SQL_PATH" | grep -q '^-- K-QCENTER configuration sync generated' || { echo "Not a K-QCENTER configuration sync file" >&2; exit 1; }

# Make sure the latest schema migration has run before writing new columns.
curl --fail --silent --show-error http://127.0.0.1:8089/api/index.php?action=health >/dev/null

sudo install -d -m 0750 "$BACKUP_PATH"
sudo mariadb-dump --single-transaction --routines --triggers kqcenter | gzip -9 | sudo tee "$BACKUP_PATH/kqcenter-before-config-$STAMP.sql.gz" >/dev/null
echo "Backup: $BACKUP_PATH/kqcenter-before-config-$STAMP.sql.gz"

sudo mariadb --batch kqcenter < "$SQL_PATH"

sudo mariadb --batch kqcenter -e "SELECT 'departments' t,COUNT(*) n FROM departments WHERE active=1 UNION ALL SELECT 'services',COUNT(*) FROM services WHERE active=1 UNION ALL SELECT 'kiosk_templates',COUNT(*) FROM kiosk_templates WHERE active=1 UNION ALL SELECT 'kiosk_menu_items',COUNT(*) FROM kiosk_menu_items UNION ALL SELECT 'weekly_hours',COUNT(*) FROM weekly_hours"
curl --fail --silent --show-error http://127.0.0.1:8089/api/index.php?action=health
echo
echo "K-QCENTER configuration sync complete."
